css:
.hero {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: radial-gradient(ellipse at 50% 0%, rgba(108,99,255,0.3) 0%, transparent 70%),
              radial-gradient(ellipse at 80% 80%, rgba(255,99,108,0.15) 0%, transparent 50%),
              #0A0A0F;
  padding: 2rem;
}
.hero-content {
  text-align: center;
  max-width: 720px;
}
.hero-title {
  font-size: clamp(2.5rem, 6vw, 5rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.05;
  color: #fff;
  margin-bottom: 1.5rem;
}
.hero-sub {
  font-size: 1.25rem;
  color: rgba(255,255,255,0.6);
  line-height: 1.7;
  margin-bottom: 2.5rem;
}
.hero-cta { display: flex; gap: 1rem; justify-content: center; flex-wrap: wrap; }
.btn-primary {
  padding: 0.875rem 2rem;
  background: #6C63FF;
  color: #fff;
  border-radius: 8px;
  font-weight: 600;
  text-decoration: none;
  transition: opacity 0.2s;
}
.btn-primary:hover { opacity: 0.85; }
.btn-ghost {
  padding: 0.875rem 2rem;
  border: 1px solid rgba(255,255,255,0.2);
  color: rgba(255,255,255,0.8);
  border-radius: 8px;
  font-weight: 500;
  text-decoration: none;
}

.split-hero {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 4rem;
  align-items: center;
  min-height: 100vh;
  padding: 6rem 5%;
  max-width: 1280px;
  margin: 0 auto;
}
.split-text h1 { font-size: clamp(2rem, 4vw, 3.5rem); font-weight: 800; letter-spacing: -0.03em; line-height: 1.1; }
.split-text p { color: #666; font-size: 1.1rem; line-height: 1.7; margin: 1.5rem 0; }
.badge {
  display: inline-block;
  padding: 0.25rem 0.75rem;
  background: rgba(108,99,255,0.1);
  color: #6C63FF;
  border: 1px solid rgba(108,99,255,0.3);
  border-radius: 100px;
  font-size: 0.8rem;
  font-weight: 600;
  margin-bottom: 1.5rem;
}
.app-mockup {
  background: #111;
  border-radius: 12px;
  aspect-ratio: 16/10;
  border: 1px solid rgba(255,255,255,0.08);
  box-shadow: 0 50px 100px rgba(0,0,0,0.4);
}
@media (max-width: 768px) { .split-hero { grid-template-columns: 1fr; } }

.bento-section { padding: 6rem 5%; max-width: 1280px; margin: 0 auto; }
.bento-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;
}
.bento-card {
  background: #111;
  border: 1px solid rgba(255,255,255,0.07);
  border-radius: 16px;
  padding: 2rem;
  transition: border-color 0.2s;
}
.bento-card:hover { border-color: rgba(108,99,255,0.4); }
.bento-hero { grid-column: span 3; background: linear-gradient(135deg, #1a0a2e, #2d1b69); }
.bento-wide { grid-column: span 2; }
.bento-tall { grid-row: span 2; }
.feature-icon { font-size: 2.5rem; margin-bottom: 1rem; }
.bento-card h2, .bento-card h3 { color: #fff; font-weight: 700; margin-bottom: 0.75rem; }
.bento-card p { color: rgba(255,255,255,0.5); font-size: 0.95rem; line-height: 1.6; }

.fullscreen-section {
  position: relative;
  width: 100%;
  height: 100vh;
  overflow: hidden;
  display: flex;
  align-items: center;
  justify-content: center;
}
.bg-video {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}
.video-overlay {
  position: absolute;
  inset: 0;
  background: linear-gradient(to bottom, rgba(0,0,0,0.5) 0%, rgba(0,0,0,0.7) 100%);
}
.video-content {
  position: relative;
  z-index: 1;
  text-align: center;
  color: #fff;
}
.video-content h1 {
  font-size: clamp(2.5rem, 6vw, 7rem);
  font-weight: 800;
  letter-spacing: -0.04em;
}

.cards-section { padding: 6rem 5%; max-width: 1280px; margin: 0 auto; }
.cards-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1.5rem;
}
.card {
  background: #111;
  border: 1px solid rgba(255,255,255,0.08);
  border-radius: 16px;
  padding: 2.5rem;
  transition: transform 0.25s ease, box-shadow 0.25s ease;
}
.card:hover {
  transform: translateY(-6px);
  box-shadow: 0 20px 60px rgba(0,0,0,0.4);
}
.card.featured {
  background: #6C63FF;
  border-color: transparent;
}

.magazine-layout { max-width: 1280px; margin: 0 auto; padding: 4rem 5%; }
.mag-title {
  font-size: clamp(3rem, 7vw, 7rem);
  font-weight: 900;
  letter-spacing: -0.04em;
  line-height: 0.95;
  margin: 1rem 0 3rem;
}
.mag-content {
  display: grid;
  grid-template-columns: 55% 1fr;
  gap: 4rem;
  align-items: start;
}
.mag-image { width: 100%; aspect-ratio: 4/3; object-fit: cover; border-radius: 8px; }
.mag-lead { font-size: 1.35rem; line-height: 1.6; font-weight: 300; margin-bottom: 1.5rem; }
